-- Demo data for a copier / printer service business in Delhi NCR, dated around the day it's loaded:
-- 15 customers and their machines, 4 engineers, ~3 months of closed complaints (parts and charges),
-- 7 pending today (3 older than two days, 4 with Ramesh, 1 not yet assigned), and AMC contracts -
-- 5 expiring in the next few weeks and 2 that lapsed last week without renewal.
-- Sharma Traders (Canon iR 2525): 3 visits in 3 months, 2 of them paper jams.

-- Fills the shared workspace once. Internal: called by desk_session_seeded() and reset_demo().
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.seed_demo() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  cust uuid;
BEGIN
  PERFORM set_config('app.via', 'seed', true);
  UPDATE __APP_SCHEMA__.settings SET demo_seeded_at = now(), business_name = 'Your Copier Service';
  PERFORM set_config('app.via', '', true);
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.seed_demo() FROM PUBLIC, anon, authenticated;

-- "Reset demo data" (admin only): clears the workspace's data and loads the sample again.
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.reset_demo() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
BEGIN
  IF NOT __APP_SCHEMA__.is_admin() THEN
    RAISE EXCEPTION 'Only the admin can reset the demo data.' USING ERRCODE = '42501';
  END IF;
  DELETE FROM __APP_SCHEMA__.activity_log;
  DELETE FROM __APP_SCHEMA__.amc_contracts;
  DELETE FROM __APP_SCHEMA__.complaints;
  DELETE FROM __APP_SCHEMA__.machines;
  DELETE FROM __APP_SCHEMA__.customers;
  DELETE FROM __APP_SCHEMA__.engineers WHERE member_user_id IS NULL;
  PERFORM __APP_SCHEMA__.seed_demo();
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.reset_demo() FROM PUBLIC, anon;

-- First admin sign-in also loads the demo data.
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.desk_session_seeded() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
DECLARE
  session jsonb := __APP_SCHEMA__.desk_session();
BEGIN
  IF session IS NOT NULL AND session ->> 'status' = 'active' AND NOT (session ->> 'demo_seeded')::boolean THEN
    PERFORM pg_advisory_xact_lock(hashtext('__APP_SCHEMA__.seed'));
    IF NOT EXISTS (SELECT 1 FROM __APP_SCHEMA__.settings WHERE demo_seeded_at IS NOT NULL) THEN
      PERFORM __APP_SCHEMA__.seed_demo();
    END IF;
    session := session || jsonb_build_object('demo_seeded', true, 'business_name', (SELECT business_name FROM __APP_SCHEMA__.settings));
  END IF;
  RETURN session;
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.desk_session_seeded() FROM PUBLIC, anon;

